function render(){head();navRender();let views={dashboard:dash,market,garage,workshop,ledger};document.getElementById('content').innerHTML=`<div class="view">${views[state.screen]()}</div>`}
function addLog(type,title,amount,detail){state.ledger.unshift({type,title,amount,detail,day:state.day})}
function buyCar(id){let c=state.market.find(x=>x.id===id);if(!c||state.cash<c.ask)return;state.cash-=c.ask;state.inventory.push({...c,id:uid(),parts:[]});addLog('purchase','Bought '+c.name,c.ask,'Vehicle purchase');state.market=state.market.filter(x=>x.id!==id);toast('Nice find. '+c.name+' is yours.');render()}
function sellCar(id){let i=state.inventory.findIndex(x=>x.id===id);if(i<0)return;let c=state.inventory[i],value=carValue(c),offer=Math.round(value*(.94+Math.random()*.12));state.cash+=offer;state.rep=Math.min(100,state.rep+Math.max(1,Math.round(c.cond/18)));addLog('sale','Sold '+c.name,offer,'Retail sale · '+c.cond+'% condition');state.inventory.splice(i,1);if(state.selectedId===id)state.selectedId=state.inventory[0]?.id||null;toast('Sold for '+money(offer)+'! Reputation +'+Math.max(1,Math.round(c.cond/18)));render()}
function installPart(carId,partId){let c=state.inventory.find(x=>x.id===carId),p=partCatalog.find(x=>x.id===partId);if(!c||!p||state.cash<p.cost||(c.parts||[]).includes(partId))return;state.cash-=p.cost;c.parts.push(partId);c.cond=Math.min(100,c.cond+Math.round(p.boost/500));addLog('part','Installed '+p.name,p.cost,c.name);toast(p.name+' installed. Value is up!');render()}
function selectForBuild(id){state.selectedId=id;go('workshop')}
function nextDay(){state.day++;makeMarket();let income=state.inventory.length?Math.min(250,state.inventory.length*45):0;if(income){state.cash-=income;addLog('part','Lot & upkeep',income,'Daily operating costs')}toast('Day '+state.day+' — fresh listings just landed.');render()}
document.getElementById('nextDay').onclick=nextDay;
render();
</script></body></html>

